        internal static IReadOnlyList<DikozemieNativePerkTier> GetSkill(string skillId)
        {
            var result = new List<DikozemieNativePerkTier>();
            foreach (IGrouping<int, DikozemieNativePerkDefinition> group in
                Definitions.Where(perk => string.Equals(
                        perk.SkillId,
                        skillId,
                        StringComparison.OrdinalIgnoreCase))
                    .GroupBy(perk => perk.Tier)
                    .OrderBy(group => group.Key))
            {
                DikozemieNativePerkDefinition top = group.First();
                DikozemieNativePerkDefinition bottom = group.FirstOrDefault(perk =>
                    string.Equals(
                        perk.StringId,
                        top.AlternativeId,
                        StringComparison.Ordinal));
                if (bottom == null && group.Count() > 1)
                {
                    bottom = group.Skip(1).First();
                }
                result.Add(new DikozemieNativePerkTier
                {
                    RequiredLevel = top.RequiredLevel,
                    Top = top,
                    Bottom = bottom
                });
            }
            return result;
        }

        internal static int GetPreviousRequiredLevel(
            string skillId,
            int requiredLevel)
        {
            return Definitions
                .Where(perk => string.Equals(
                    perk.SkillId,
                    skillId,
                    StringComparison.OrdinalIgnoreCase) &&
                    perk.RequiredLevel < requiredLevel)
                .Select(perk => perk.RequiredLevel)
                .DefaultIfEmpty(0)
                .Max();
        }

        internal static bool IsPerkChoice(
            string skillId,
            int requiredLevel,
            string perkId)
        {
            return Definitions.Any(perk =>
                string.Equals(perk.SkillId, skillId, StringComparison.OrdinalIgnoreCase) &&
                perk.RequiredLevel == requiredLevel &&
                string.Equals(perk.StringId, perkId, StringComparison.Ordinal));
        }

        internal static bool TryGetDefinition(
            string perkId,
            out DikozemieNativePerkDefinition definition)
        {
            definition = Definitions.FirstOrDefault(perk =>
                !string.IsNullOrWhiteSpace(perkId) &&
                string.Equals(perk.StringId, perkId, StringComparison.Ordinal));
            return definition != null;
        }

        private static DikozemieNativePerkDefinition P(
            string skillId,
            int tier,
            string stringId,
            string alternativeId,
            string nameText,
            string primaryDescription,
            float primaryValue,
            bool primaryPercent,
            string secondaryDescription,
            float secondaryValue,
            bool secondaryPercent)
        {
            return new DikozemieNativePerkDefinition
            {
                SkillId = skillId,
                Tier = tier,
                RequiredLevel = TierSkillRequirements[tier - 1],
                StringId = stringId,
                AlternativeId = alternativeId,
                NameText = nameText,
                PrimaryDescriptionText = primaryDescription,
                PrimaryValue = primaryValue,
                PrimaryPercent = primaryPercent,
                SecondaryDescriptionText = secondaryDescription,
                SecondaryValue = secondaryValue,
                SecondaryPercent = secondaryPercent
            };
        }
    }
